"""The plane-parallel bispectrum terms generated by mathwap (bk/PP_.py): NPP, GR1, GR2 and PNG, angle-dependent, three
tracers.

Their multipoles against every analytic one CosmoWAP has (bk and bk_mt - GR2 also checks the (H/k)^2 part of Z2 that
mathwap's bk port lacked before), their forms against MathWAP's single-tracer ones, and the multipoles they add (l4,
m > 0, bk_mt's ylm) against numerical integration of those forms.
"""

import numpy as np
import pytest

import cosmo_wap as cw
from cosmo_wap import bk, bk_mt
from cosmo_wap.bk import PP_
from cosmo_wap.lib import utils
from cosmo_wap.lib.angular_integrate import ylm

K1, K2, TH = np.array([0.02, 0.05, 0.08, 0.1]), np.array([0.015, 0.04, 0.05, 0.1]), np.array([2.0, 1.2, 2.6, 2.1])
ZZ = 1.0
ANALYTIC = {"NPP": ["l0", "l2"], "GR1": ["l1", "l3", "l1m1", "l3m1", "l3m2", "l3m3"], "GR2": ["l0", "l2"]}
FORMS = {"NPP": bk.Bk_0, "GR1": bk.GR_1, "GR2": bk.GR_2}


def _lm(name):
    return int(name[1]), int(name[3]) if "m" in name else 0


@pytest.fixture(scope="module")
def three_tracers(cosmo):
    """faint, bright, bright - every leg's tracer matters"""
    sp = cw.SurveyParams.Euclid(cosmo)
    sp.BF_split(6e-16)
    return cw.ClassWAP(cosmo, [sp.faint, sp.bright, sp.bright], verbose=False)


@pytest.mark.parametrize("name", ANALYTIC)
def test_single_tracer_matches_analytic(cosmo_funcs, name):
    k3 = utils.get_k3(TH, K1, K2)
    for meth in ANALYTIC[name]:
        want = getattr(getattr(bk, name), meth)(cosmo_funcs, K1, K2, k3, TH, ZZ)
        got = PP_._lm(name, *_lm(meth), cosmo_funcs, K1, K2, k3, TH, ZZ, 0, 0)
        np.testing.assert_allclose(got, want, rtol=1e-11, atol=1e-13 * np.abs(want).max(), err_msg=meth)


@pytest.mark.parametrize("name", ANALYTIC)
def test_forms_match_mathwap(cosmo_funcs, name):
    """and they do not depend on the LOS"""
    mu, phi = np.array([0.3, -0.7, 0.95])[:, None], np.array([0.4, 2.2])[None, :]
    want = FORMS[name](mu, phi, cosmo_funcs, 0.05, 0.04, None, 1.2, ZZ)
    for r, s in [(0, 0), (0.3, 0.2)]:
        got = getattr(PP_, name + "_")(mu, phi, cosmo_funcs, 0.05, 0.04, None, 1.2, ZZ, r, s)
        np.testing.assert_allclose(got, want, rtol=1e-12)


@pytest.mark.parametrize("name", ["NPP", "GR2"])
def test_added_multipoles_match_integration(cosmo_funcs, name):
    """the l4 and m > 0 methods bk lacked, against 32-node integration of MathWAP's forms - and with FoG against 48 nodes,
    where the added methods integrate at n=24 (~1e-7 at l4m4)"""
    cls = getattr(bk, name)
    for l, m in [(4, 0), (2, 1), (2, 2), (4, 1), (4, 2), (4, 3), (4, 4)]:
        meth = getattr(cls, f"l{l}" + (f"m{m}" if m else ""))
        for sigma, n, rtol in [(None, 32, 1e-9), (4.0, 48, 1e-6)]:
            want = np.squeeze(ylm(FORMS[name], l, m, cosmo_funcs, K1, K2, None, TH, ZZ, sigma=sigma, n=n))
            got = meth(cosmo_funcs, K1, K2, None, TH, ZZ, sigma=sigma)
            np.testing.assert_allclose(
                got, want, rtol=rtol, atol=rtol * 1e-3 * np.abs(want).max(), err_msg=f"{l}{m} {sigma}"
            )


@pytest.mark.parametrize("name", ANALYTIC)
def test_multi_tracer_matches_analytic(three_tracers, name):
    meths = {"NPP": ["l0", "l2", "l4"], "GR1": ["l1", "l3"], "GR2": ["l0", "l2"]}[name]
    for meth in meths:
        want = getattr(getattr(bk_mt, name), meth)(three_tracers, K1, K2, None, TH, ZZ)
        got = PP_._lm(name, *_lm(meth), three_tracers, K1, K2, None, TH, ZZ, 0, 0)
        np.testing.assert_allclose(got, want, rtol=1e-11, atol=1e-13 * np.abs(want).max(), err_msg=meth)


def test_multi_tracer_gr2_l4_and_ylm(three_tracers):
    """bk_mt.GR2.l4 is not the export's zero stand-in (it never had l4): l4 and ylm agree with each other, and with FoG
    tend to the undamped as sigma -> 0"""
    args = (three_tracers, K1, K2, None, TH, ZZ)
    l4 = bk_mt.GR2.l4(*args)
    assert np.abs(l4).max() > 1e-3 * np.abs(bk_mt.GR2.l0(*args)).max()  # not the stand-in's zeros
    np.testing.assert_allclose(bk_mt.GR2.ylm(4, 0, *args), l4, rtol=1e-12)
    np.testing.assert_allclose(bk_mt.GR2.ylm(4, 0, *args, sigma=1e-3), l4, rtol=1e-6)
    for name in ANALYTIC:
        assert hasattr(getattr(bk_mt, name), "ylm") and hasattr(getattr(bk_mt, name), "l4m4")


# ---------------------------------------------------------------------------
# PNG: PNG1 (linear in fNL, bk's) and PNG3 (the whole tree, bk_mt's) - one polynomial for every shape
# ---------------------------------------------------------------------------

SHAPES = ["Loc", "Eq", "Orth"]


@pytest.fixture(scope="module")
def three_tracers_png(cosmo):
    sp = cw.SurveyParams.Euclid(cosmo)
    sp.BF_split(6e-16)
    return cw.ClassWAP(cosmo, [sp.faint, sp.bright, sp.bright], compute_bias=True, verbose=False)


@pytest.mark.parametrize("shape", SHAPES)
def test_png_matches_analytic(cosmo_funcs_png, three_tracers_png, shape):
    """fNL = 37 as well, so bk_mt's fNL^2 and fNL^3 are checked too"""
    for fNL in (1.0, 37.0):
        for l in (0, 2):
            want = getattr(getattr(bk, shape), f"l{l}")(cosmo_funcs_png, K1, K2, None, TH, ZZ, fNL=fNL)
            got = PP_._lm("PNG1", l, 0, cosmo_funcs_png, K1, K2, None, TH, ZZ, 0, 0, shape=shape, fNL=fNL)
            np.testing.assert_allclose(got, want, rtol=1e-11, atol=1e-13 * np.abs(want).max())
            want = getattr(getattr(bk_mt, shape), f"l{l}")(three_tracers_png, K1, K2, None, TH, ZZ, fNL=fNL)
            got = PP_._lm("PNG3", l, 0, three_tracers_png, K1, K2, None, TH, ZZ, 0, 0, shape=shape, fNL=fNL)
            np.testing.assert_allclose(got, want, rtol=1e-11, atol=1e-13 * np.abs(want).max())


@pytest.mark.parametrize("shape", SHAPES)
def test_png_added_multipoles(cosmo_funcs_png, shape):
    """the form against MathWAP's, and the methods bk lacked against integrating it - fNL_<shape> overrides fNL"""
    mu, phi = np.array([0.3, -0.7])[:, None], np.array([0.4, 2.2])[None, :]
    form = getattr(bk, shape + "_")
    np.testing.assert_allclose(
        PP_.PNG1_(mu, phi, cosmo_funcs_png, 0.05, 0.04, None, 1.2, ZZ, shape=shape, fNL=3.0),
        form(mu, phi, cosmo_funcs_png, 0.05, 0.04, None, 1.2, ZZ, fNL=3.0),
        rtol=1e-12,
    )
    cls = getattr(bk, shape)
    for l, m in [(4, 0), (2, 1), (4, 4)]:
        want = np.squeeze(ylm(form, l, m, cosmo_funcs_png, K1, K2, None, TH, ZZ, n=32, fNL=3.0))
        got = getattr(cls, f"l{l}" + (f"m{m}" if m else ""))(cosmo_funcs_png, K1, K2, None, TH, ZZ, fNL=3.0)
        np.testing.assert_allclose(got, want, rtol=1e-9, atol=1e-12 * np.abs(want).max())
    override = {f"fNL_{shape.lower()}": 3.0}
    np.testing.assert_allclose(
        cls.l4(cosmo_funcs_png, K1, K2, None, TH, ZZ, **override),
        cls.l4(cosmo_funcs_png, K1, K2, None, TH, ZZ, fNL=3.0),
    )


def test_png_multi_tracer_has_ylm(three_tracers_png):
    args = (three_tracers_png, K1, K2, None, TH, ZZ)
    for shape in SHAPES:
        cls = getattr(bk_mt, shape)
        np.testing.assert_allclose(cls.ylm(4, 2, *args, fNL=2.0), cls.l4m2(*args, fNL=2.0), rtol=1e-12)
